questionvariables.text:
/* [modulus, missing remainder] */
vlist: [[3, 2], [3, 0], [4, 2], [4, 3], [5, 0], [6, 4]];
vpick: rand(vlist);
md: vpick[1];
rmiss: vpick[2];
listed: sublist(makelist(jj, jj, 0, md - 1), lambda([jj], jj # rmiss));
caselist: map(lambda([jj], n = md*k + jj), listed);
ncases: length(caselist);
ta1: md*k + rmiss;
/* Other correct forms: a different constant, a negative coefficient. */
talt1: md*k + rmiss - md;
talt2: -md*k + rmiss;
/* Diagnostics: a case already listed; the wrong multiple of k. */
dlisted: md*k + mod(rmiss + 1, md);
dmult: 2*md*k + rmiss;
/* Validators run with simp:false, so simplify explicitly. */
validate_case(ex) := if not(atom(ex)) and is(op(ex) = "=") then "Type only the expression for \\(n\\), without \\(n =\\)."
  else if not(member(k, listofvars(ex))) then "Your expression should contain the integer \\(k\\)."
  else if listofvars(ex) # [k] then "Use only the letter \\(k\\)."
  else if not(is(ev(hipow(expand(ex), k), simp) = 1)) or not(is(ev(expand(ex - coeff(expand(ex), k, 1)*k - coeff(expand(ex), k, 0)), simp) = 0)) then "The expression should be a whole number times \\(k\\) plus a whole number."
  else if not(integerp(ev(coeff(expand(ex), k, 1), simp)) and integerp(ev(coeff(expand(ex), k, 0), simp))) then "Use whole-number coefficients."
  else "";
s_assert(is(member(mod(rmiss + 1, md), listed)), true);

feedbackvariables.text:
sa: ev(expand(ans1), simp);
ca: coeff(sa, k, 1);
cb: coeff(sa, k, 0);
rgot: mod(cb, md);
